window.__posterData({"id": "emma-doris-morcos", "name": "Emma Doris Morcos", "folder": "Week1_Poster_AI_EmmaDorisMorcos.", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "//EMMA: After putting in the first prompt from the assignment description the code became much longer (around 100 more lines of code). Even if it shortened parts of the code that I had written originally (for example, the rave text), it also added a lot of extra things, created many more variables and functions. There are a few things that were added that we had covered in class such as arrays, const variables, if statements and functions as well as many new concepts that I am not familar with. \n\n//EMMA: Also after adding the later prompt which let AI add additional things that it wanted it added a shockwave effect around the mouse pointer, nudging the background balls around.\n\n\n// Rave poster: a dense field of small bouncing balls over a background image,\n// a stack of \"RAVE\" rows where some rows slide back and forth, and a jittery\n// circle that follows the mouse. On every beat (128 BPM) a shockwave ring\n// blasts out from the mouse circle and kicks the balls outward.\n// Everything that moves freezes while the mouse is pressed.\n\nconst PALETTE = ['#f09b51', '#49b1e2', '#000000', '#d94c6c'];\n\n// --- \"RAVE\" rows -----------------------------------------------------------\n\n//EMMA: AI has organised the the text RAVE at the top as variables instead of 50 lines of code for each rave line, putting the text where it should be, the textsize, how many words there are and where they sit on the poster\nconst RAVE_TEXT_SIZE = 120;\nconst ROW_START_Y = 20;\nconst ROW_SPACING = 25;\nconst ROW_COUNT = 31;           // baselines 20, 45, ... 770\nconst FIXED_ROW_X = 6;          // x of the rows that don't move\n// Rows that slide: every third row, except row 17 slides instead of row 18\n// (kept exactly as in the original layout).\n\n//EMMA: AI made an array for the words that slide across the screen\nconst SLIDING_ROWS = new Set([0, 3, 6, 9, 12, 15, 17, 20, 23, 26, 29]);\n\nlet slidingX = 6;               // x of the sliding rows\nlet slidingSpeed = 6;           // horizontal speed of the sliding rows\n\n// --- Name line -------------------------------------------------------------\n\n//EMMA: created a variable for my name with the text format also as variables\nconst NAME = 'Emma Doris Morcos';\nconst NAME_TEXT_SIZE = 65;\nconst NAME_X = 6;\nconst NAME_Y = 795;\n\n// --- Bouncing balls --------------------------------------------------------\n// Many small balls flying in random directions and bouncing off all four\n// edges of the poster. Their colours flicker through the palette every\n// frame, so the field reads almost like TV static.\n\n//EMMA: created variables for the balls and also adding many more balls. this was the element that I asked AI to add because of the design critique session we had around the rave poster.\n\n//EMMA: This was my AI prompt: Change how the balls in the background are bouncing. Make the balls bounce randomly around the posters diameter while making them smaller and add more balls so that it almost looks static while keeping the balls changing colours. Make the colours match the colour array that the poster already possesses.\nconst BALL_COUNT = 400;\nconst BALL_DIAMETER = 10;\nconst BALL_MIN_SPEED = 1;\nconst BALL_MAX_SPEED = 6;\n\nlet balls = [];\n\n// --- Beat shockwaves -------------------------------------------------------\n// A ring expands from the mouse circle on every beat. Balls the ring passes\n// over get a kick away from its centre, which then fades out.\n\n//EMMA: This was what AI added when i asked for what it would add. Creating a beat that flows out of the mouse while it nudges the smallballs around in the background\nconst BPM = 128;\nconst BEAT_MS = 60000 / BPM;\nconst WAVE_SPEED = 16;          // px per frame the ring grows\nconst WAVE_MAX_RADIUS = 1000;   // big enough to cross the whole poster\nconst WAVE_THICKNESS = 8;\nconst WAVE_KICK = 9;            // push given to a ball the ring passes\nconst KICK_DAMPING = 0.9;       // how fast the push fades (per frame)\n\nlet waves = [];\nlet beatTimer = 0;\nlet beatCount = 0;\n\n// --- Mouse circle ----------------------------------------------------------\nconst MOUSE_CIRCLE_DIAMETER = 100;\nconst MOUSE_JITTER = 30;\n\nlet mouseColorIndex = 0;\n\nlet img;\n\nasync function setup() {\n  createCanvas(600, 800);\n\n  img = await loadImage('background.jpg');\n  describe('liquid metall');\n\n  //EMMA: AI created the balls that are in the background in setup instead of draw\n\n  const r = BALL_DIAMETER / 2;\n  for (let i = 0; i < BALL_COUNT; i++) {\n    // Random position anywhere on the poster, random direction and speed\n    const angle = random(TWO_PI);\n    const speed = random(BALL_MIN_SPEED, BALL_MAX_SPEED);\n    balls.push({\n      x: random(r, width - r),\n      y: random(r, height - r),\n      vx: cos(angle) * speed,\n      vy: sin(angle) * speed,\n      kx: 0,                    // extra velocity from shockwaves\n      ky: 0,\n    });\n  }\n}\n\nfunction draw() {\n  image(img, 0, 0);\n\n\n  //EMMA: I wanted the balls to pause but also dissapear when the mouse is pressed but AI made the balls pause but stay in view. I don't know why it did that and it went against my design vision where when pressed the poster becomes calm.\n  const paused = mouseIsPressed;\n\n  if (!paused) {\n    updateBeat();\n    updateWaves();\n    updateBalls();\n  }\n  drawBalls();\n\n  drawRaveRows();\n  drawName();\n  drawWaves();\n\n  if (!paused) slidingX += slidingSpeed;\n  bounceSlidingRows();\n\n  if (!paused) drawMouseCircle();\n}\n\n// Fire a new shockwave on every beat. The timer only advances while the\n// poster isn't paused, so holding the mouse also stops the beat.\n\n//EMMA: this was also added when I asked AI to suggest it's own additions to the poster; making a beat/shockwave flow from the pointer. This added to the rave feeling but was not what I was expecting it to do. I think it created a very chaotic feeling but also when the mouse is pressed the ring doesnt dissapear which again goes against my vision of creating a more calm feeling when everything is paused\nfunction updateBeat() {\n  beatTimer += deltaTime;\n  if (beatTimer >= BEAT_MS) {\n    beatTimer -= BEAT_MS;\n    spawnWave();\n  }\n}\n\n//EMMA: while this was also added when AI could add it's own suggestion, creating the shockwave rings and colouring them with the colour palette\nfunction spawnWave() {\n  // Start at the mouse if it's on the poster, otherwise at the centre\n  const onCanvas = mouseX > 0 && mouseX < width && mouseY > 0 && mouseY < height;\n  waves.push({\n    x: onCanvas ? mouseX : width / 2,\n    y: onCanvas ? mouseY : height / 2,\n    r: 0,\n    // Step through the palette so consecutive beats change colour\n    colour: PALETTE[beatCount % PALETTE.length],\n  });\n  beatCount++;\n}\n\n// Grow each ring, kick the balls it passes over, and drop finished rings.\n\n//EMMA: while this was also added when AI could add it's own suggestion, making the balls in the background be nudged by the shockwaves\nfunction updateWaves() {\n  for (const w of waves) {\n    const inner = w.r;\n    w.r += WAVE_SPEED;\n\n    for (const b of balls) {\n      const d = dist(w.x, w.y, b.x, b.y);\n      // The ring front crossed this ball during this frame\n      if (d > inner && d <= w.r && d > 0) {\n        const falloff = 1 - w.r / WAVE_MAX_RADIUS; // weaker further out\n        b.kx += ((b.x - w.x) / d) * WAVE_KICK * falloff;\n        b.ky += ((b.y - w.y) / d) * WAVE_KICK * falloff;\n      }\n    }\n  }\n  waves = waves.filter((w) => w.r < WAVE_MAX_RADIUS);\n}\n\n// Rings fade out as they grow.\nfunction drawWaves() {\n  push();\n  noFill();\n  strokeWeight(WAVE_THICKNESS);\n  for (const w of waves) {\n    const c = color(w.colour);\n    c.setAlpha(255 * (1 - w.r / WAVE_MAX_RADIUS));\n    stroke(c);\n    circle(w.x, w.y, w.r * 2);\n  }\n  pop();\n}\n\n// Move each ball and bounce it off the poster's edges.\n\n//EMMA: this was how AI \nfunction updateBalls() {\n  const r = BALL_DIAMETER / 2;\n  for (const b of balls) {\n    b.x += b.vx + b.kx;\n    b.y += b.vy + b.ky;\n    b.kx *= KICK_DAMPING;\n    b.ky *= KICK_DAMPING;\n\n    if (b.x < r || b.x > width - r) {\n      b.vx *= -1;\n      b.kx *= -1;\n      b.x = constrain(b.x, r, width - r);\n    }\n    if (b.y < r || b.y > height - r) {\n      b.vy *= -1;\n      b.ky *= -1;\n      b.y = constrain(b.y, r, height - r);\n    }\n  }\n}\n\n// Draw every ball in a random palette colour (re-picked each frame).\nfunction drawBalls() {\n  noStroke();\n  for (const b of balls) {\n    fill(random(PALETTE));\n    circle(b.x, b.y, BALL_DIAMETER);\n  }\n}\n\n// Stack of \"RAVE\" rows cycling through the palette.\n\n//EMMA: AI shortned the 50 lines of text code that i wrote into one loop using the variables and array to shorten the code. \nfunction drawRaveRows() {\n  textSize(RAVE_TEXT_SIZE);\n  for (let row = 0; row < ROW_COUNT; row++) {\n    fill(PALETTE[row % PALETTE.length]);\n    const x = SLIDING_ROWS.has(row) ? slidingX : FIXED_ROW_X;\n    text('RAVE', x, ROW_START_Y + row * ROW_SPACING);\n  }\n}\n\n//EMMA: this was how AI wrote my name at the end. This felt like a more difficult way to do this\nfunction drawName() {\n  textSize(NAME_TEXT_SIZE);\n  fill(PALETTE[3]);\n  text(NAME, NAME_X, NAME_Y);\n}\n\n// Reverse the sliding rows at the edges.\nfunction bounceSlidingRows() {\n  // Measured at the current text size (the name's size), as in the original.\n  const maxX = width - textWidth('rave');\n  if (slidingX <= 0 || slidingX >= maxX) {\n    slidingSpeed *= -1;\n  }\n}\n\n// Circle jittering around the mouse in a palette colour.\n\n//EMMA: AI somehow got rid of the border around the circle that jitters around the mouse, thought it says strokeweight 1 just as it did before so i'm not sure how it's done this. AI also made the code take all information from the variables it created for the balls other than defining the size in this part of the code. \nfunction drawMouseCircle() {\n  fill(PALETTE[mouseColorIndex]);\n  strokeWeight(1);\n  // Pick the colour for the next frame\n  mouseColorIndex = floor(random(PALETTE.length));\n  circle(\n    mouseX + random() * MOUSE_JITTER,\n    mouseY + random() * MOUSE_JITTER,\n    MOUSE_CIRCLE_DIAMETER\n  );\n}", "assets": {"background.jpg": {"mime": "image/webp", "b64": ""}}});
